const initialLanguage=()=>{try{const stored=window.localStorage.getItem(LANGUAGE_KEY);if(stored===LANGUAGES.EN||stored===LANGUAGES.ES_AR)return stored}catch(_){ }const preferred=(navigator.languages&&navigator.languages[0])||navigator.language||'';return String(preferred).toLowerCase().startsWith('es')?LANGUAGES.ES_AR:LANGUAGES.EN};
const copy=(key)=>{const value=COPY[key];return value?(state.language===LANGUAGES.EN?value.en:value.es):key};
const get=(id)=>DEMO_PRODUCTS.find(p=>p.id===id);
const money=(n)=>new Intl.NumberFormat(state.language===LANGUAGES.EN?'en-US':'es-AR',{maximumFractionDigits:0}).format(n);
const currency=(n)=>'ARS '+money(n);
const nativeAmount=(value)=>{const raw=String(value??'').trim();if(!/^\d+(?:\.\d+)?$/.test(raw))return null;const [whole,fraction]=raw.split('.');const grouping=state.language===LANGUAGES.EN?',':'.';const decimal=state.language===LANGUAGES.EN?'.':',';const grouped=whole.replace(/\B(?=(\d{3})+(?!\d))/g,grouping);return fraction?`${grouped}${decimal}${fraction}`:grouped};
const nativeCurrency=(value,currencyCode='ARS')=>{const formatted=nativeAmount(value);return formatted?`${safe(currencyCode||'ARS')} ${formatted}`:currency(Number(value)||0)};
const icons=(name)=>`<svg aria-hidden="true"><use href="#i-${name}"></use></svg>`;
const safe=(value)=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const PRODUCT_LABEL_KEYS=Object.freeze({'Ejemplo de precio bajo':'sampleLabel','Sachet 1 L':'sachetLabel','Variedad liviana':'lightLabel','Tetra Brik':'tetraLabel','Almacén básico':'pantryLabel','Aceites y grasas':'oilsLabel'});
