const SEARCH_ALIASES=Object.freeze({milk:'leche',rice:'arroz',oil:'aceite'});
const productLabel=(product)=>copy(PRODUCT_LABEL_KEYS[product.label]||'fictitious');
const productVariant=(product)=>copy(PRODUCT_VARIANT_KEYS[product.id])||product.variant;
