 const state={page:'home',selected:'milk-serenisima-1l',from:'search',query:'leche',sort:'price',category:'Todos',saved:new Set(),basket:new Map(),detailQuantity:1,searchScroll:0,theme:'light',language:initialLanguage(),tripInputs:{distance:'',consumption:'',fuel:'',tolls:'0',parking:'0'},observedPriceForm:{amount:'',currency:'ARS',date:'',time:'',utcOffset:'-03:00',artifactId:'',proofType:''},demo:true,nativeSearchEnabled:true,nativeSearchPending:false,nativeSearchState:null,nativeProducts:new Map(),nativeDetailPending:false,nativeDetailState:null,nativeSavedEnabled:true,nativeSavedPending:false,nativeSavedState:null,nativeTripEnabled:true,nativeTripPending:false,nativeTripState:null,nativeObservedPricePending:false,nativeObservedPriceSelection:null,nativeObservedPricePrefill:null,nativeObservedPriceConfirmation:null,nativeStapleWatchPending:false,nativeStapleWatchState:null,history:[],matrixSort:'unit',matrixStore:'all',matrixScrollTop:0,matrixScrollLeft:0,matrixSuppressClickUntil:0};
