function enableNativeSearch(){state.nativeSearchEnabled=true;state.nativeSearchState=null;requestNativeSearch(state.query)}
function disableNativeSearch(){state.nativeSearchEnabled=false;state.nativeSearchPending=false;state.nativeSearchState=null;render()}
function nativeProductId(generation,index){return 'native-'+String(generation||0)+'-'+String(index)}
function receiveNativeSearch(payload){if(!payload||typeof payload!=='object')return;state.nativeSearchPending=false;state.nativeSearchState=payload;state.nativeDetailPending=false;state.nativeDetailState=null;state.nativeProducts.clear();(payload.matches||[]).forEach((match,index)=>{const id=nativeProductId(payload.generation,index);state.nativeProducts.set(id,{id,native:true,brand:match.brand||'',name:match.displayName||'',quantity:match.packageQuantityLabel||'',match});});render()}
function receiveNativeProductDetail(payload){if(!payload||typeof payload!=='object'||!payload.match)return;const match=payload.match;const id=nativeProductId(payload.generation||state.nativeSearchState?.generation||0,0);state.nativeProducts.set(id,{id,native:true,brand:match.brand||'',name:match.displayName||'',quantity:match.packageQuantityLabel||'',match});state.nativeDetailPending=false;state.nativeDetailState={...payload,id};state.selected=id;state.from='search';navigate('detail',{selected:id,from:'search'});}
function nativeMatchLabel(value){const key=String(value||'').trim().toLowerCase();const copyKey={'exact barcode':'nativeMatchExactBarcode','exact name':'nativeMatchExactName','name match':'nativeMatchName','name prefix':'nativeMatchPrefix','possible typo match':'nativeMatchTypo','provider identity match':'nativeMatchProvider'}[key];return copyKey?copy(copyKey):copy('nativeIdentityOnly')}
function nativeFreshnessLabel(value){switch(String(value||'').trim().toUpperCase()){case'FRESH':return copy('nativeFreshRecent');case'STALE':return copy('nativeFreshStale');case'UNKNOWN':return copy('nativeFreshUnknown');default:return copy('nativeFreshUnknown')}}
const NATIVE_STATUS_COPY=Object.freeze({'Search a product in the qualified Argentina area.':'nativeStatusSearch','Searching Argentina product identities…':'nativeStatusSearching','Loading more matching identities…':'nativeStatusMoreLoading','No matching product identity was found in this release.':'nativeStatusNoMatches','Qualified product identities and listed-price evidence found. This release reached the bounded result limit.':'nativeStatusQualifiedLimit','Qualified product identities and listed-price evidence found. More matching identities are available.':'nativeStatusQualifiedMore','Qualified product identities and listed-price evidence found. No more matching identities were returned in this release.':'nativeStatusQualifiedDone','Product identities found. This release reached the bounded result limit.':'nativeStatusIdentitiesLimit','Product identities found. More matching identities are available.':'nativeStatusIdentitiesMore','Product identities found. No more matching identities were returned in this release.':'nativeStatusIdentitiesDone'});
function nativeStatus(payload){switch(payload?.mode){case'AUTHORIZATION_UNAVAILABLE':return copy('nativeUnavailable');case'TEMPORARILY_UNAVAILABLE':return copy('nativeTemporary');case'TIMEOUT':case'LOADING':return copy('nativeTimeout');case'STALE_RELEASE':return copy('nativeStale');case'NO_MATCHES':return copy('nativeNoMatches');default:{const status=payload?.statusMessage;const key=NATIVE_STATUS_COPY[status];return key?copy(key):copy('nativeSearchIntro')}}}
