function requestNativeObservedProofPicker(){try{if(window.ValuePilotHost&&typeof window.ValuePilotHost.postMessage==='function'){window.ValuePilotHost.postMessage(JSON.stringify({type:'SELECT_NATIVE_OBSERVED_PROOF'}));return}}catch(_){ }flash(copy('nativeJourneyUnavailable'))}
