function requestNativeStapleClearSelection(){try{if(window.ValuePilotHost&&typeof window.ValuePilotHost.postMessage==='function'){window.ValuePilotHost.postMessage(JSON.stringify({type:'CLEAR_NATIVE_STAPLE_SELECTION'}));return}}catch(_){ }flash(copy('nativeJourneyUnavailable'))}
