function observedNativeMessage(message){const raw=String(message||'');if(state.language===LANGUAGES.EN)return raw;if(raw.includes('required fields'))return copy('observedConfirmMissing');if(raw.includes('Checking the confirmation'))return copy('observedConfirmSubmitting');if(raw.includes('Observed price confirmed'))return copy('observedConfirmSuccess');if(raw.includes('could not be completed')||raw.includes('could not be accepted'))return copy('observedConfirmError');if(raw.includes('When the required fields'))return copy('observedConfirmReady');return raw}
function observedNativeError(error){return error?copy('observedConfirmInputError'):''}
function requestNativeTrip(values){state.nativeTripPending=true;state.nativeTripState=null;render();try{if(window.ValuePilotHost&&typeof window.ValuePilotHost.postMessage==='function'){window.ValuePilotHost.postMessage(JSON.stringify({type:'CALCULATE_NATIVE_TRIP',oneWayDistance:String(values.distance),fuelConsumption:String(values.consumption),fuelPrice:String(values.fuel),tolls:String(values.tolls),parking:String(values.parking)}));return}}catch(_){ }state.nativeTripPending=false;state.nativeTripState={status:'ERROR',error:copy('nativeTripError')};render()}
function enableNativeTrip(){state.nativeTripEnabled=true;state.nativeTripState=null;render()}
function disableNativeTrip(){state.nativeTripEnabled=false;state.nativeTripPending=false;state.nativeTripState=null;render()}
function receiveNativeTrip(payload){if(!payload||typeof payload!=='object')return;state.nativeTripPending=false;state.nativeTripState=payload;render()}
function nativeTripResults(payload){if(state.nativeTripPending)return `<div class="empty-state">${icons('route')}<strong>${copy('nativeTripLoading')}</strong><p>${copy('nativeTripIntro')}</p></div>`;if(!payload)return `<div class="empty-state">${icons('route')}<strong>${copy('nativeTripTitle')}</strong><p>${copy('nativeTripIntro')}</p></div>`;if(payload.status!=='SUCCESS'||!payload.result)return `<div class="empty-state">${icons('info')}<strong>${copy('nativeTripError')}</strong><p>${copy('nativeTripErrorDetail')}</p></div>`;const r=payload.result;return `<div class="summary-total" style="margin-top:14px"><div class="split"><span style="font-size:12px">${copy('nativeTripTotal')}</span><span class="pill" style="background:#ffffff22;color:inherit">ARS</span></div><div class="number-lg" style="margin-top:10px">${nativeCurrency(r.total)}</div><div class="micro" style="color:#dadbd5">${copy('nativeTripRoundTrip')}: ${safe(r.roundTripKm)} km</div><div class="trip-breakdown"><span>${copy('nativeTripFuel')} <strong>${nativeCurrency(r.fuelCost)}</strong></span><span>${copy('nativeTripTolls')} <strong>${nativeCurrency(r.tolls)}</strong></span><span>${copy('nativeTripParking')} <strong>${nativeCurrency(r.parking)}</strong></span></div></div>`}
function persistLanguage(language){try{window.localStorage.setItem(LANGUAGE_KEY,language)}catch(_){ }try{if(window.ValuePilotHost&&typeof window.ValuePilotHost.postMessage==='function')window.ValuePilotHost.postMessage(JSON.stringify({type:'SET_LANGUAGE',language:language}))}catch(_){ }}
function setLanguage(next,options={}){const language=next===LANGUAGES.ES_AR?LANGUAGES.ES_AR:LANGUAGES.EN;const scroll=window.scrollY||document.documentElement.scrollTop;if(state.language===language){updateChrome();return}state.language=language;if(options.persist!==false)persistLanguage(language);render();requestAnimationFrame(()=>window.scrollTo({top:scroll,behavior:'auto'}))}
function updateChrome(){document.documentElement.lang=state.language;document.title=copy('pageTitle');document.body.classList.toggle('search-clean',state.page==='search');const description=document.querySelector('meta[name=description]');if(description)description.setAttribute('content',copy('metaDescription'));const set=(id,value)=>{const element=document.getElementById(id);if(element)element.textContent=value};const live=Boolean(state.nativeSearchEnabled&&state.nativeSearchState&&state.nativeSearchState.mode==='READY');set('demoRibbonTitle',live?copy('nativeSearchTitle'):copy('demoTitle'));set('demoRibbonMessage','· '+(live?copy('nativeEvidence'):copy('demoMessage')));const demoRibbon=document.querySelector('#demoRibbon');if(demoRibbon)demoRibbon.setAttribute('aria-label',copy('demoAria'));set('brandLocation','Buenos Aires (CABA)');set('navHomeLabel',copy('navHome'));set('navSearchLabel',copy('navSearch'));set('navBasketLabel',copy('navBasket'));set('navSavedLabel',copy('navSaved'));const brand=document.querySelector('#brandButton');if(brand)brand.setAttribute('aria-label',copy('backHome'));const theme=document.querySelector('#themeToggle');if(theme){theme.setAttribute('aria-label',copy('themeAria'));theme.setAttribute('title',copy('themeTitle'))}const settingsButton=document.querySelector('#settingsButton');if(settingsButton)settingsButton.setAttribute('aria-label',copy('preferences'));if(nav)nav.setAttribute('aria-label',copy('navLabel'));document.querySelectorAll('.language-toggle').forEach(group=>group.setAttribute('aria-label',copy('language')));document.querySelectorAll('[data-language]').forEach(button=>{const active=button.dataset.language===state.language;button.setAttribute('aria-pressed',active?'true':'false');button.setAttribute('aria-label',button.dataset.language===LANGUAGES.EN?copy('english'):copy('spanishArgentina'))})}
function render(){if(state.page==='search')saveScroll();main.innerHTML=({home:home,search:search,detail:detail,basket:basket,saved:saved,trip:trip,settings:settings,'observed-price':observedPrice,'observed-confirm':observedConfirm,'staple-watch':stapleWatch,'private-history':privateHistory})[state.page]();updateChrome();const parentNav=['home','search','basket','saved'].includes(state.from)?state.from:'search';nav.querySelectorAll('button[data-nav]').forEach(btn=>{const active=btn.dataset.nav===state.page||((state.page==='detail'||state.page==='trip')&&btn.dataset.nav===parentNav);btn.classList.toggle('active',active);btn.setAttribute('aria-current',active?'page':'false')});const nativeCount=nativeDataMode()&&state.nativeSavedState?Number(state.nativeSavedState.items?.length||0):0;const count=nativeDataMode()?nativeCount:basketCount();bubble.hidden=!count;bubble.textContent=count;requestAnimationFrame(()=>{const matrix=document.querySelector('#matrixScroll');if(matrix){installMatrixPan(matrix);matrix.scrollTop=state.matrixScrollTop||0;matrix.scrollLeft=state.matrixScrollLeft||0}});}
function home(){const native=Boolean(state.nativeSavedState&&nativeDataMode());const items=native?Array.isArray(state.nativeSavedState.items)?state.nativeSavedState.items:[]:[];const count=native?items.length:basketCount();return `<section class="content"><div class="home-intro"><div class="row"><span class="pill orange">● ${copy('unitPrices')}</span><span class="pill">CABA</span></div><h1 class="hero-title">${copy('heroTitle')}</h1><p class="hero-copy">${copy('heroCopy')}</p></div>
  <div class="search-bar home-search">${icons('search')}<input id="homeQuery" aria-label="${safe(copy('searchProduct'))}" placeholder="${safe(copy('searchPlaceholder'))}" value="${safe(state.query)}"><button class="btn btn-primary" data-action="go-search">${copy('search')} ${icons('arrow')}</button></div>
  <div class="home-stat"><div class="card card-dark"><div class="module-title">${native?copy('nativeBasketTitle'):copy('demoBasket')} <span class="pill" style="float:right;background:#ffffff26;color:inherit">${itemCount(count)}</span></div><div><div class="number-lg">${native?(count?itemCount(count):copy('basketTitle')):(basketCount()?currency(basketSum()):copy('basketTitle'))}</div><p class="micro">${native?copy('nativeEvidence'):(basketCount()?copy('samplePrices'):copy('basketEmptyCopy'))}</p></div><button class="btn btn-outline" style="font-size:11px" data-nav="basket">${copy('viewBasket')} ${icons('arrow')}</button></div>
  <div class="card"><div class="module-title">${native?copy('nativeTripTitle'):copy('tripPlanner')}</div><div class="number-lg" style="font-size:22px;margin-top:12px">${copy('nextTrip')}</div><p class="small">${native?copy('nativeTripIntro'):copy('tripCopy')}</p><button class="btn btn-primary btn-fill" data-nav="trip">${icons('route')} ${copy('planTrip')}</button></div></div>
  <div class="section-header"><strong>${copy('comparison')}</strong><button data-nav="search">${copy('viewAll')} ${icons('arrow')}</button></div><div class="home-cats"><button class="chip active" data-action="category" data-category="Leche">${copy('dairy')}</button><button class="chip" data-action="category" data-category="Arroz">${copy('pantry')}</button><button class="chip" data-action="category" data-category="Aceite">${copy('oils')}</button></div>
  <div class="section-header"><strong>${copy('sampleUnitPrices')}</strong><span class="micro">${copy('demoOnly')}</span></div>
  <div class="stack">${[DEMO_PRODUCTS[1],DEMO_PRODUCTS[4]].map(p=>`<div class="card"><div class="split"><div><span class="pill">${safe(p.quantity)}</span><strong style="display:block;margin-top:7px;font-size:13px">${safe(p.brand)} · ${safe(p.name)}</strong></div><button class="bookmark-button" data-action="add" data-id="${p.id}" aria-label="${safe(copy('addToBasket'))}: ${safe(p.name)}">${icons('plus')}</button></div><div class="split" style="margin-top:8px"><span class="number-lg" style="font-size:20px">${currency(p.price)}</span><span class="micro">${safe(p.store)}</span></div></div>`).join('')}</div>
  <div class="preview-notice" style="margin-top:15px">${icons('info')}<span>${copy('demoNumbers')}</span></div></section>`}
function filtered(){const rawQuery=state.query.toLocaleLowerCase('es-AR').trim();const q=SEARCH_ALIASES[rawQuery]||rawQuery;let data=DEMO_PRODUCTS.filter(p=>!q||[p.brand,p.name,p.variant,p.quantity,p.store].join(' ').toLocaleLowerCase('es-AR').includes(q));if(state.category!=='Todos')data=data.filter(p=>[p.brand,p.name,p.variant].join(' ').toLocaleLowerCase('es-AR').includes(state.category.toLocaleLowerCase('es-AR')));data.sort((a,b)=>state.sort==='price'?(a.price/a.liters-b.price/b.liters):state.sort==='name'?a.brand.localeCompare(b.brand):b.price/b.liters-a.price/a.liters);return data}
const MATRIX_DEMO_ROWS=Object.freeze(Array.from({length:1000},(_,index)=>{const p=DEMO_PRODUCTS[index%DEMO_PRODUCTS.length];const multiplier=1+((index*17)%19)/100;const pack=Math.round(p.price*multiplier);return {id:'demo-matrix-'+index,demoId:p.id,product:p.name,brand:p.brand,quantity:p.quantity,unitValue:pack/p.liters,unitCurrency:'ARS',unitBasis:p.unit==='L'?'L':'kg',packValue:pack,packCurrency:'ARS',store:p.store,distance:null,fuel:null,total:null,fixture:true}}));
function matrixMoney(value,currencyCode='ARS'){if(value==null||!Number.isFinite(Number(value)))return '—';return `${safe(currencyCode||'ARS')} ${nativeAmount(Number(value))||money(Number(value))}`}
function matrixRowsForDemo(){const q=String(state.query||'').toLocaleLowerCase('es-AR').trim();const category=String(state.category||'Todos').toLocaleLowerCase('es-AR');return MATRIX_DEMO_ROWS.filter(row=>{const hay=[row.product,row.brand,row.quantity,row.store].join(' ').toLocaleLowerCase('es-AR');return (!q||hay.includes(SEARCH_ALIASES[q]||q))&&(category==='todos'||[row.product,row.brand].join(' ').toLocaleLowerCase('es-AR').includes(category))})}
function finiteDistance(value){const distance=Number(value);return Number.isFinite(distance)&&distance>=0?distance:null}
function distanceLabel(value){const distance=finiteDistance(value);if(distance==null)return '';return distance<1?`${Math.round(distance*1000)} m`:`${distance<10?distance.toFixed(1):distance.toFixed(0)} km`}
function matrixRowsForNativeFlat(payload){const generation=payload?.generation||0;return (payload?.matches||[]).flatMap((match,index)=>{const offers=Array.isArray(match.offers)&&match.offers.length?match.offers:[null];const id=nativeProductId(generation,index);return offers.map((offer,offerIndex)=>({id,product:match.displayName||'',brand:match.brand||'',quantity:match.packageQuantityLabel||'',unitValue:offer?.unitPriceAmount!=null?Number(offer.unitPriceAmount):null,unitCurrency:offer?.unitPriceCurrency||offer?.currency||'ARS',unitBasis:offer?.unitPriceBasis||'',packValue:offer?.priceAmount!=null?Number(offer.priceAmount):null,packCurrency:offer?.currency||'ARS',store:offer?.storeName||'',freshness:offer?.freshness||'',distance:offer?.distanceKm!=null?finiteDistance(offer.distanceKm):null,fuel:null,total:null,native:true,match,identityKey:match.identityKey||'',offerKey:offer?.offerKey||'',query:payload?.query||state.query,offerIndex}))})}
function matrixRowsForNative(payload){
  const seen=new Set();
  return matrixRowsForNativeFlat(payload).map(row=>{
    const key=row.identityKey||[row.product,row.brand,row.quantity].join('|');
    const hideIdentity=seen.has(key);
    seen.add(key);
    return {...row,hideIdentity};
  });
}function matrixIdentityCount(rows){return new Set(rows.map(row=>row.identityKey||[row.product,row.brand,row.quantity].join('|'))).size}
function matrixRowMeta(row){return [row.brand,row.quantity].map(value=>String(value||'').trim()).filter(Boolean).join(' · ')}
function matrixRowsSorted(rows){const direction=state.matrixSort==='product'||state.matrixSort==='store'?'asc':'asc';const value=(row,key)=>{const n=Number(row[key]);return Number.isFinite(n)?n:null};return [...rows].sort((a,b)=>{let result=0;switch(state.matrixSort){case'pack':result=(value(a,'packValue')??Infinity)-(value(b,'packValue')??Infinity);break;case'store':result=String(a.store||'').localeCompare(String(b.store||''));break;case'distance':result=(value(a,'distance')??Infinity)-(value(b,'distance')??Infinity);break;case'unit':default:result=(value(a,'unitValue')??Infinity)-(value(b,'unitValue')??Infinity);break}return result||String(a.product||'').localeCompare(String(b.product||''))||String(a.brand||'').localeCompare(String(b.brand||''))})}
function matrixStoreOptions(rows){const stores=new Map();rows.forEach(row=>{const name=String(row.store||'').trim();if(!name)return;const distance=finiteDistance(row.distance);const current=stores.get(name);if(!current||current.distance==null||(distance!=null&&distance<current.distance))stores.set(name,{name,distance})});return [...stores.values()].sort((a,b)=>(a.distance??Infinity)-(b.distance??Infinity)||a.name.localeCompare(b.name))}
function matrixFilteredRows(rows){const hasStore=state.matrixStore!=='all'&&rows.some(row=>String(row.store||'')===state.matrixStore);const filtered=hasStore?rows.filter(row=>String(row.store||'')===state.matrixStore):rows;return matrixRowsSorted(filtered)}
function matrixSortLabel(){switch(state.matrixSort){case'pack':return copy('matrixSortPack');case'product':return copy('matrixSortProduct');case'store':return copy('matrixSortStore');case'distance':return copy('matrixSortDistance');default:return copy('matrixSortUnit')}}
function matrixRow(row,index,native){const productAction=native?'native-detail':'detail';const productAttrs=native?`data-identity-key="${safe(row.identityKey)}" data-query="${safe(row.query||state.query)}"`:`data-id="${safe(row.demoId)}"`;const photoId=native?row.id:row.demoId;const unit=row.unitValue==null?'—':matrixMoney(row.unitValue,row.unitCurrency);const pack=row.packValue==null?'—':matrixMoney(row.packValue,row.packCurrency);const unitLabel=row.unitValue==null?copy('matrixUnavailable'):row.unitBasis?`ARS / ${safe(row.unitBasis)}`:'ARS / unit';const freshness=native?(row.freshness?nativeFreshnessLabel(row.freshness):copy('matrixUnavailable')):copy('matrixSample');const addAction=native?'native-save':'add';const mapAction=native?'native-map':'demo-map';const ariaProduct=`${safe(row.product)}${row.brand?` · ${safe(row.brand)}`:''}`;const distance=distanceLabel(row.distance);const rowMeta=matrixRowMeta(row);const actions=`<div class="matrix-product-actions"><button class="matrix-action" data-action="photos" data-id="${safe(photoId)}" aria-label="${safe(copy('matrixGoogleImages'))}: ${ariaProduct}" title="${safe(copy('matrixGoogleImages'))}">${icons('camera')}</button><button class="matrix-action" data-action="${mapAction}" data-identity-key="${safe(row.identityKey||'')}" data-offer-key="${safe(row.offerKey||'')}" data-query="${safe(row.query||state.query)}" aria-label="${safe(copy('matrixOpenMap'))}: ${safe(row.store||'')}" title="${safe(copy('matrixOpenMap'))}">${icons('pin')}</button><button class="matrix-action matrix-add" data-action="${addAction}" data-id="${safe(photoId)}" aria-label="${safe(native?copy('matrixAddNative'):copy('matrixAddDemo'))}: ${ariaProduct}" title="${safe(native?copy('matrixAddNative'):copy('matrixAddDemo'))}">${icons('plus')}</button></div>`;return `<tr class="matrix-row" data-action="${productAction}" ${productAttrs} tabindex="0" aria-label="${ariaProduct}, ${safe(row.quantity||'')}, ${safe(pack)} pack price, ${safe(unit)} per unit, ${safe(row.store||'')}${distance?`, ${distance}`:''}"><td class="matrix-product ${row.hideIdentity?'matrix-product-duplicate':''}"><div class="matrix-name" title="${ariaProduct}">${safe(row.product)}</div><div class="matrix-meta" title="${safe(rowMeta)}">${safe(rowMeta)}</div>${actions}</td><td class="matrix-pack right"><span class="matrix-money">${safe(pack)}</span></td><td class="matrix-unit right"><div class="matrix-unit-value">${safe(unit)}</div><div class="matrix-unit-label">${unitLabel}</div></td><td class="matrix-store"><span title="${safe(row.store||'')}">${safe(row.store||copy('nativeIdentityOnly'))}</span><small>${safe(freshness)}</small></td><td class="matrix-distance right ${row.distance==null?'unavailable':''}">${row.distance==null?'—':safe(distance)}</td><td class="matrix-fuel right ${row.fuel==null?'unavailable':''}">${row.fuel==null?'—':matrixMoney(row.fuel,'ARS')}</td><td class="matrix-total right ${row.total==null?'unavailable':''}">${row.total==null?'—':matrixMoney(row.total,'ARS')}</td></tr>`}
function matrixTable(rows,native){const sourceRows=matrixFilteredRows(rows);const stores=matrixStoreOptions(rows);const label=native?copy('matrixNativeRows'):copy('matrixDemoRows');const identityCount=matrixIdentityCount(sourceRows);const summary=native?`${sourceRows.length} ${label} · ${identityCount} ${copy('matrixNativeProducts')}`:`${sourceRows.length} ${label}`;return `<div class="matrix-summary"><strong>${summary}</strong><span>${native?copy('matrixEvidence'):copy('matrixDemoNote')}</span></div><div class="matrix-scroll" id="matrixScroll" tabindex="0" aria-label="${safe(copy('matrixAria'))}"><table class="price-matrix"><thead><tr><th class="matrix-product"><button data-action="matrix-sort" data-sort="product">${copy('matrixProduct')} <span>↕</span></button></th><th class="matrix-pack right"><button data-action="matrix-sort" data-sort="pack">${copy('matrixPack')} <span>↕</span></button></th><th class="matrix-unit right"><button data-action="matrix-sort" data-sort="unit">${copy('matrixUnit')} <span>↓</span></button></th><th class="matrix-store"><button data-action="matrix-sort" data-sort="store">${copy('matrixStore')} <span>↕</span></button></th><th class="matrix-distance right"><button data-action="matrix-sort" data-sort="distance">${copy('matrixDistance')} <span>↕</span></button></th><th class="matrix-fuel right">${copy('matrixFuel')}</th><th class="matrix-total right">${copy('matrixTripTotal')}</th></tr></thead><tbody>${sourceRows.length?sourceRows.map((row,index)=>matrixRow(row,index,native)).join(''):`<tr><td class="matrix-empty" colspan="7">${copy('matrixNoMatches')}</td></tr>`}</tbody></table></div><div class="matrix-footnote"><span>${copy('matrixPinned')}</span><span class="matrix-sidehint">${copy('matrixMoreColumns')}</span></div>`}
function search(){const native=state.nativeSearchEnabled;const nativeRows=matrixRowsForNative(state.nativeSearchState);const stores=matrixStoreOptions(nativeRows);const storeOptions=stores.map(store=>`<option value="${safe(store.name)}" ${state.matrixStore===store.name?'selected':''}>${safe(store.name)}${store.distance!=null?` · ${safe(distanceLabel(store.distance))}`:''}</option>`).join('');return `<section class="content search-content"><div class="search-context"><span class="pill orange">ARS · CABA</span><span class="preview-origin" title="${safe(copy('previewOriginNote'))}">${icons('pin')}<span><strong>${copy('previewOriginLabel')}</strong> · ${copy('previewOriginAddress')}</span></span></div><form class="search-bar" id="searchForm">${icons('search')}<input id="searchQuery" name="query" autocomplete="off" aria-label="${safe(copy('searchInput'))}" placeholder="${safe(copy('nameBrandQuantity'))}" value="${safe(state.query)}"><button class="icon-button" type="button" id="clearQuery" aria-label="${safe(copy('clearSearch'))}">${icons('close')}</button><button class="btn btn-primary" type="submit" aria-label="${safe(copy('search'))}">${icons('arrow')}</button></form><div class="matrix-controlbar"><label>${copy('matrixStoreFilter')}<select id="matrixStore" aria-label="${safe(copy('matrixStoreFilter'))}"><option value="all" ${state.matrixStore==='all'?'selected':''}>${copy('matrixAllStores')}</option>${storeOptions}</select></label><label>${copy('matrixSortFilter')}<select id="matrixSort" aria-label="${safe(copy('matrixSortFilter'))}"><option value="unit" ${state.matrixSort==='unit'?'selected':''}>${copy('matrixSortUnit')}</option><option value="pack" ${state.matrixSort==='pack'?'selected':''}>${copy('matrixSortPack')}</option><option value="product" ${state.matrixSort==='product'?'selected':''}>${copy('matrixSortProduct')}</option><option value="store" ${state.matrixSort==='store'?'selected':''}>${copy('matrixSortStore')}</option><option value="distance" ${state.matrixSort==='distance'?'selected':''}>${copy('matrixSortDistance')}</option></select></label><span class="matrix-control-hint">${safe(matrixSortLabel())}</span></div><div class="chip-row search-categories"><button class="chip ${state.category==='Todos'?'active':''}" data-action="category" data-category="Todos">${copy('all')}</button><button class="chip ${state.category==='Leche'?'active':''}" data-action="category" data-category="Leche">${copy('milk')}</button><button class="chip ${state.category==='Arroz'?'active':''}" data-action="category" data-category="Arroz">${copy('rice')}</button><button class="chip ${state.category==='Aceite'?'active':''}" data-action="category" data-category="Aceite">${copy('oil')}</button></div><div id="resultsArea">${native?nativeResults(state.nativeSearchState):searchUnavailable()}</div></section>`}
function results(items){return matrixTable(matrixRowsForDemo(),false)}
function searchUnavailable(){return `<div class="empty-state search-empty">${icons('info')}<strong>${copy('nativeUnavailable')}</strong><p>${copy('nativeEvidence')}</p></div>`}
function nativeClarification(payload){const clarification=payload?.clarification;if(!clarification||!Array.isArray(clarification.choices)||clarification.choices.length<2)return '';const choices=clarification.choices.slice(0,6).map(choice=>{const label=state.language===LANGUAGES.EN?(choice.labelEn||choice.label):choice.label;return `<button class="clarification-choice" type="button" data-action="native-clarification" data-query="${safe(choice.query||'')}" aria-label="${safe(label)}"><span>${safe(label)}</span>${icons('arrow')}</button>`}).join('');return `<div class="card search-clarification" role="group" aria-labelledby="searchClarificationTitle"><div class="section-label" id="searchClarificationTitle">${copy('searchClarificationTitle')}</div><p class="small">${copy('searchClarificationBody')}</p><div class="clarification-choices">${choices}</div><div class="micro">${copy('searchClarificationObserved')}</div></div>`}
function nativeResults(payload){if(state.nativeSearchPending&&!payload)return `<div class="empty-state search-empty">${icons('search')}<strong>${copy('nativeLoading')}</strong><p>${copy('nativeEvidence')}</p></div>`;if(!payload)return `<div class="empty-state search-empty">${icons('search')}<strong>${copy('searchProduct')}</strong><p>${copy('nativeEvidence')}</p></div>`;const matches=payload.matches||[];if(payload.mode==='AUTHORIZATION_UNAVAILABLE'||payload.mode==='TEMPORARILY_UNAVAILABLE'||payload.mode==='TIMEOUT'||payload.mode==='LOADING'||payload.mode==='STALE_RELEASE')return `<div class="empty-state search-empty">${icons('info')}<strong>${copy('nativeUnavailable')}</strong><p>${safe(nativeStatus(payload))}</p></div>`;const clarification=nativeClarification(payload);if(!matches.length)return clarification||`<div class="empty-state search-empty">${icons('search')}<strong>${copy('nativeNoMatches')}</strong><p>${safe(nativeStatus(payload))}</p></div>`;const more=payload.hasMore?`<div class="stack" style="margin-top:14px"><button class="btn btn-soft btn-fill" data-action="native-load-more" ${state.nativeSearchPending?'disabled':''}>${state.nativeSearchPending?copy('nativeLoadingMore'):copy('nativeLoadMore')} ${icons('arrow')}</button></div>`:'';return clarification+matrixTable(matrixRowsForNative(payload),true)+more}
function nativeProductCard(match,generation,index){return matrixRow({id:nativeProductId(generation,index),product:match.displayName||'',brand:match.brand||'',quantity:match.packageQuantityLabel||'',native:true,match,identityKey:match.identityKey||'',query:state.query,offerKey:''},index,true)}
function productCard(p,i){const saved=state.saved.has(p.id);return `<article class="product-card"><div class="product-tags"><span class="pill ${i===0?'green':''}">${i===0?copy('lowestExample'):safe(productLabel(p))}</span><span class="pill">${safe(p.quantity)}</span><button class="bookmark-button ${saved?'is-saved':''}" data-action="save" data-id="${p.id}" aria-label="${safe(saved?copy('removeSavedProductAria'):copy('saveProductAria'))}: ${safe(p.name)}">${icons('bookmark')}</button></div>
  <button class="product-main" data-action="detail" data-id="${p.id}"><div class="product-brand">${safe(p.brand)} <span style="font-weight:450">· ${safe(p.name)}</span></div><div class="product-description">${safe(productVariant(p))}</div></button>
  <div class="price-slab" aria-label="${safe(copy('fictitiousPrice'))} ${money(p.price)} ${safe(copy('pesos'))}"><div><div class="slab-label">${copy('unitPriceSample')}</div><div class="number-lg">${priceTag(p)}</div></div><div class="package-price">${copy('packageTotal')}<br><strong>${currency(p.price)}</strong></div></div>
  <div class="store-line"><span class="row">${icons('store')} ${safe(p.store)}</span><span>● ${copy('fictitious')}</span></div>
  <div class="product-actions"><button class="btn btn-soft" data-action="photos" data-id="${p.id}">${icons('camera')} ${copy('googleImages')}</button><button class="btn btn-accent" data-action="add" data-id="${p.id}">${icons('basket')} ${copy('addPrice')} ${currency(p.price)}</button></div></article>`}
function nativeOfferRows(match){const offers=Array.isArray(match?.offers)?match.offers:[];if(!offers.length)return `<div class="empty-state" style="padding:18px 8px">${icons('info')}<strong>${copy('nativeNoOffers')}</strong><p>${copy('nativeEvidence')}</p></div>`;return `<div class="stack">${offers.map(offer=>{const unit=offer?.unitPriceAmount!=null?nativeCurrency(offer.unitPriceAmount,offer.unitPriceCurrency||offer.currency||'ARS'):copy('nativePriceUnavailable');const pack=offer?.priceAmount!=null?nativeCurrency(offer.priceAmount,offer.currency||'ARS'):copy('nativePriceUnavailable');return `<div class="card"><div class="split"><strong>${safe(offer.storeName||copy('nativeIdentityOnly'))}</strong><span class="pill">${safe(nativeFreshnessLabel(offer.freshness))}</span></div><div class="split" style="margin-top:8px"><span class="small">${copy('nativeUnitPrice')}</span><strong>${safe(unit)}</strong></div><div class="split" style="margin-top:4px"><span class="micro">${copy('nativePackagePrice')}</span><span class="micro">${safe(pack)}</span></div></div>`}).join('')}</div>`}
function nativeDetail(){const detail=state.nativeDetailState;const match=detail?.match;if(!match)return `<section class="content"><div class="empty-state">${icons('search')}<strong>${copy('nativeStaleDetail')}</strong><button class="btn btn-primary" data-nav="search">${copy('searchProducts')}</button></div></section>`;const product=state.nativeProducts.get(detail.id)||{id:detail.id,native:true,brand:match.brand||'',name:match.displayName||'',quantity:match.packageQuantityLabel||'',match};const offers=Array.isArray(match.offers)?match.offers:[];const first=offers[0];const unit=first?.unitPriceAmount!=null?nativeCurrency(first.unitPriceAmount,first.unitPriceCurrency||first.currency||'ARS'):copy('nativePriceUnavailable');const packagePrice=first?.priceAmount!=null?nativeCurrency(first.priceAmount,first.currency||'ARS'):copy('nativePriceUnavailable');const saved=nativeSavedHas(match.identityKey);return `<section class="content"><button class="detail-back" data-action="back">${icons('back')} ${copy('backResults')}</button><div class="eyebrow">${copy('nativeDetailTitle')}</div><div class="detail-top"><span class="detail-brand">${safe(match.brand||'')} · ${copy('exampleCaba')}</span><h1 class="detail-title">${safe(match.displayName||'')}</h1><div class="small">${safe(match.packageQuantityLabel||'')} · ${safe(match.sourceLabel||copy('nativeIdentityOnly'))}</div></div><div class="detail-image-placeholder"><span class="icon-circle">${icons('camera')}</span><strong style="font-size:14px">${copy('noCatalogPhotos')}</strong><p>${copy('photoCopy')}</p><button class="btn btn-primary" data-action="photos" data-id="${safe(product.id)}">${icons('camera')} ${copy('googleAction')} ${icons('arrow')}</button><div class="disclaimer">${copy('externalDisclaimer')}</div></div><div class="detail-metric"><div class="card"><div class="eyebrow" style="font-size:9px">${copy('pricePrefix')}${copy('priceLiter')}</div><strong>${safe(unit)}</strong><div class="micro">${offers.length?copy('nativeEvidence'):copy('nativeNoOffers')}</div></div><div class="card"><div class="eyebrow" style="font-size:9px">${copy('packageTotalUpper')}</div><strong>${safe(packagePrice)}</strong><div class="micro">${safe(match.packageQuantityLabel||'')}</div></div></div><div class="section-header"><strong>${copy('context')}</strong><span class="pill orange">${offers.length} ${copy('nativeOfferCount')}</span></div>${nativeOfferRows(match)}<div class="card stack" style="margin-top:12px"><div class="small">${copy('nativeDetailIntro')}</div><button class="btn btn-accent btn-fill" data-action="native-detail-save">${icons('bookmark')} ${saved?copy('nativeSavedAction'):copy('nativeSaveAction')}</button></div></section>`}
function detail(){if(state.nativeDetailState)return nativeDetail();const p=get(state.selected)||DEMO_PRODUCTS[0];return `<section class="content"><button class="detail-back" data-action="back">${icons('back')} ${copy('backResults')}</button><div class="detail-top"><span class="detail-brand">${safe(p.brand)} · ${copy('exampleCaba')}</span><h1 class="detail-title">${safe(p.name)}</h1><div class="small">${safe(p.quantity)} · ${safe(productVariant(p))}</div></div>
  <div class="detail-image-placeholder"><span class="icon-circle">${icons('camera')}</span><strong style="font-size:14px">${copy('noCatalogPhotos')}</strong><p>${copy('photoCopy')}</p><button class="btn btn-primary" data-action="photos" data-id="${p.id}">${icons('camera')} ${copy('googleAction')} ${icons('arrow')}</button><div class="disclaimer">${copy('externalDisclaimer')}</div></div>
  <div class="detail-metric"><div class="card"><div class="eyebrow" style="font-size:9px">${copy('pricePrefix')}${p.unit==='L'?copy('priceLiter'):copy('priceKg')}</div><strong>${currency(p.price/p.liters)}</strong><div class="micro">${copy('sampleUnverified')}</div></div><div class="card"><div class="eyebrow" style="font-size:9px">${copy('packageTotalUpper')}</div><strong>${currency(p.price)}</strong><div class="micro">${safe(p.quantity)} · ${copy('sampleWord')}</div></div></div>
  <div class="section-header"><strong>${copy('context')}</strong><span class="pill orange">${copy('onlyDemo')}</span></div><div class="card"><div class="split"><div class="row">${icons('store')} <strong style="font-size:12px">${safe(p.store)}</strong></div><span class="pill">${copy('illustrative')}</span></div><p class="small">${copy('evidenceCopy')}</p><div class="preview-notice">${icons('info')} ${copy('noEvidence')}</div></div>
  <div class="section-header"><strong>${copy('basketDemo')}</strong></div><div class="card"><div class="split"><span class="small">${copy('quantityPackages')}</span><div class="qty-controls"><button data-action="detail-minus" aria-label="${safe(copy('reduce'))}">${icons('minus')}</button><span>${state.detailQuantity}</span><button data-action="detail-plus" aria-label="${safe(copy('increase'))}">${icons('plus')}</button></div></div><button class="btn btn-accent btn-fill" style="margin-top:13px" data-action="add-detail">${icons('basket')} ${copy('addDetail')} ${state.detailQuantity} · ${currency(p.price*state.detailQuantity)}</button></div></section>`}
function demoBasket(){const items=[...state.basket].filter(([id])=>get(id));return `<section class="content"><div class="page-top"><div><div class="eyebrow">${copy('privateBasket')}</div><h1 class="page-title">${copy('basketTitle')}</h1><div class="small">${copy('basketSubtitle')}</div></div><span class="pill">${itemCount(basketCount())}</span></div><div class="card stack" style="margin-top:12px"><button class="tap-link" data-action="open-native-basket">${icons('basket')} ${copy('openNativeBasket')}</button><p class="micro">${copy('openNativeBasketDetail')}</p></div>${items.length?`<div class="card"><div class="section-label" style="margin:0 0 9px">${copy('basketProducts')}</div>${items.map(([id,qty])=>{const p=get(id);return `<div class="basket-entry"><div class="item-label"><strong>${safe(p.brand)} · ${safe(p.name)}</strong><small>${safe(p.quantity)} · ${copy('samplePrice')} ${currency(p.price)}</small></div><div class="qty-controls"><button data-action="basket-minus" data-id="${id}" aria-label="${safe(copy('removeOne'))}">${icons('minus')}</button><span>${qty}</span><button data-action="basket-plus" data-id="${id}" aria-label="${safe(copy('addOne'))}">${icons('plus')}</button></div></div>`}).join('')}</div><div class="summary-total" style="margin-top:12px"><div class="split"><span style="font-size:12px">${copy('exampleTotal')}</span><span class="pill" style="background:#ffffff22;color:inherit">${copy('notVerified')}</span></div><div class="number-lg" style="margin-top:10px">${currency(basketSum())}</div><div class="micro" style="color:#dadbd5">${copy('notOffer')}</div></div><div class="stack" style="margin-top:13px"><button class="btn btn-primary btn-fill" data-nav="trip">${icons('route')} ${copy('estimateTravel')}</button><button class="btn btn-soft btn-fill" data-nav="search">${copy('keepSearching')} ${icons('arrow')}</button><button class="tap-link" data-action="clear-basket">${copy('clearDemo')}</button></div>`:`<div class="empty-state">${icons('basket')}<strong>${copy('emptyBasket')}</strong><p>${copy('chooseExamples')}</p><button class="btn btn-primary" data-nav="search">${copy('exploreProducts')} ${icons('arrow')}</button></div>`}<div class="preview-notice" style="margin-top:14px">${icons('info')} ${copy('basketNotice')}</div></section>`}
function nativeBasket(){if(state.nativeSavedPending)return `<section class="content"><div class="empty-state">${icons('basket')}<strong>${copy('nativeLoading')}</strong><p>${copy('nativeBasketIntro')}</p></div></section>`;const payload=state.nativeSavedState;const items=payload?.items||[];const basket=payload?.basket;if(!items.length)return `<section class="content"><div class="page-top"><div><div class="eyebrow">${copy('nativeBasketTitle')}</div><h1 class="page-title">${copy('basketTitle')}</h1><div class="small">${copy('nativeBasketIntro')}</div></div><span class="pill">0</span></div><div class="empty-state">${icons('basket')}<strong>${copy('nativeBasketEmpty')}</strong><p>${copy('nativeEvidence')}</p><button class="btn btn-primary" data-nav="search">${copy('searchProducts')} ${icons('arrow')}</button></div></section>`;const lines=basket?.lines||items.map(item=>({identityKey:item.identityKey,productName:item.displayName,packageQuantityText:item.packageQuantityLabel||'',lineTotalText:null,storeName:null,availabilityText:copy('nativeBasketUnknown'),missing:true}));const plan=basket?.plan;const planLoading=Boolean(basket?.planLoading);const canPlan=Boolean(basket?.canPlan);return `<section class="content"><div class="page-top"><div><div class="eyebrow">${copy('nativeBasketTitle')}</div><h1 class="page-title">${copy('basketTitle')}</h1><div class="small">${copy('nativeBasketIntro')}</div></div><span class="pill">${itemCount(items.length)}</span></div><div class="stack" style="margin-top:12px">${lines.map(line=>`<div class="card basket-entry"><div class="item-label"><strong>${safe(line.productName||'')}</strong><small>${safe(line.packageQuantityText||'')} · ${safe(line.missing?copy('nativeBasketUnknown'):(line.lineTotalText||''))}</small>${line.storeName?`<small>${safe(line.storeName)}</small>`:''}</div><button class="bookmark-button is-saved" data-action="native-remove-saved" data-identity-key="${safe(line.identityKey)}" aria-label="${safe(copy('nativeBasketRemove'))}">${icons('bookmark')}</button></div>`).join('')}</div>${plan?.totalText?`<div class="summary-total" style="margin-top:12px"><div class="split"><span style="font-size:12px">${copy('nativeBasketPlan')}</span><span class="pill" style="background:#ffffff22;color:inherit">ARS</span></div><div class="number-lg" style="margin-top:10px">${safe(plan.totalText)}</div><div class="micro" style="color:#dadbd5">${safe(plan.coverageText||'')}</div></div>`:''}<div class="card stack" style="margin-top:12px"><strong>${copy('nativeBasketTitle')}</strong><p class="micro">${safe(basket?.evidenceNotice||copy('nativeEvidence'))}</p>${basket?.errorNotice?`<div class="preview-notice">${icons('info')} ${safe(basket.errorNotice)}</div>`:''}${planLoading?`<div class="preview-notice">${icons('info')} ${copy('nativeBasketPlanLoading')}</div>`:canPlan?`<button class="btn btn-accent btn-fill" data-action="native-plan">${icons('route')} ${copy('nativeBasketPlanAction')}</button>`:''}<button class="btn btn-primary btn-fill" data-nav="trip">${icons('route')} ${copy('estimateTravel')}</button><button class="btn btn-soft btn-fill" data-nav="search">${copy('keepSearching')} ${icons('arrow')}</button><button class="tap-link" data-action="native-refresh-saved">${copy('nativeBasketRefresh')}</button></div></section>`}
function nativeDataMode(){return state.nativeSearchEnabled&&state.nativeSavedEnabled}
function basket(){return nativeDataMode()?nativeBasket():demoBasket()}
function nativeSavedResults(payload){if(state.nativeSavedPending)return `<div class="empty-state">${icons('bookmark')}<strong>${copy('nativeLoading')}</strong><p>${copy('nativeSavedIntro')}</p></div>`;if(!payload||payload.mode==='UNAVAILABLE')return `<div class="empty-state">${icons('info')}<strong>${copy('nativeSavedTitle')}</strong><p>${copy('nativeSavedIntro')}</p></div>`;const items=payload.items||[];return items.length?`<div class="section-header" style="margin:15px 0 10px"><strong>${items.length} ${copy('saved')}</strong><span class="micro">${copy('nativeSavedIdentityNote')}</span></div><div class="stack">${items.map(item=>`<div class="card saved-card"><div><strong style="font-size:13px">${safe(item.brand?item.brand+' · ':'')}${safe(item.displayName||'')}</strong><div class="micro">${safe(item.packageQuantityLabel||'')} · ${copy('nativeSavedIdentityNote')}</div><div class="micro">${safe(item.sourceLabel||'')}</div><div class="row" style="margin-top:8px"><button class="tap-link" data-action="native-good-price" data-identity-key="${safe(item.identityKey)}" data-display-name="${safe(item.displayName||'')}">${icons('check')} ${copy('goodPriceTool')}</button><button class="tap-link" data-action="native-saved-photos" data-brand="${safe(item.brand||'')}" data-display-name="${safe(item.displayName||'')}" data-quantity="${safe(item.packageQuantityLabel||'')}">${icons('camera')} ${copy('nativeOpenPhotos')}</button></div></div><button class="bookmark-button is-saved" data-action="native-remove-saved" data-identity-key="${safe(item.identityKey)}" aria-label="${safe(copy('nativeRemoveAction'))}">${icons('bookmark')}</button></div>`).join('')}</div>`:`<div class="empty-state">${icons('bookmark')}<strong>${copy('nativeSavedEmpty')}</strong><p>${copy('nativeSavedIdentityNote')}</p><button class="btn btn-primary" data-nav="search">${copy('searchProducts')} ${icons('arrow')}</button></div>`}
function observedSelectionStatus(status){switch(String(status||'')){case'READY_FOR_PREFILL_CHECK':return copy('observedPriceSelectionReady');case'DISPLAY_METADATA_INCOMPLETE':return copy('observedPriceBlocked');default:return copy('observedPriceSelectionNeeded')}}
function observedPrefillMessage(value){const raw=String(value||'');if(state.language===LANGUAGES.EN)return raw;const map={'The selected saved product and store can prefill identity details for a later observed-price confirmation.':copy('observedPriceSelectionReady'),'Choose one saved product and one saved store again before checking.':copy('observedPriceSelectionNeeded'),'That saved product is no longer available. Choose a saved product again.':copy('observedPriceBlocked'),'That saved store is no longer available. Choose a saved store again.':copy('observedPriceBlocked'),'This saved product cannot be safely identified for observed-price confirmation yet.':copy('observedPriceBlocked'),'This saved product identifier cannot be verified for observed-price confirmation. Choose another saved product.':copy('observedPriceBlocked'),'The selected saved product needs a current display name before it can be checked.':copy('observedPriceBlocked'),'The selected saved store needs a current display name before it can be checked.':copy('observedPriceBlocked')};return map[raw]||copy('observedPriceBlocked')}
function observedSelectionRow(row,side){const action=row?.action||{};const kind=String(action.kind||'');const key=action.key?` data-key="${safe(action.key)}"`:'';const selected=Boolean(row?.selected);const label=kind==='CLEAR_PRODUCT'?copy('observedPriceClearProduct'):kind==='CLEAR_STORE'?copy('observedPriceClearStore'):side==='product'?copy('observedPriceChooseProduct'):copy('observedPriceChooseStore');return `<div class="card saved-card"><div class="stack" style="gap:3px"><strong style="font-size:13px">${safe(row?.title||'')}</strong><span class="micro">${selected?copy('observedPriceSelectionReady'):side==='product'?copy('observedPriceChooseProduct'):copy('observedPriceChooseStore')}</span></div><button class="btn ${selected?'btn-soft':'btn-outline'}" data-action="observed-select" data-kind="${safe(kind)}"${key}>${selected?icons('check'):icons('plus')} ${label}</button></div>`}
function nativeObservedSelection(payload){if(state.nativeObservedPricePending&&!payload?.selection)return `<div class="empty-state">${icons('bookmark')}<strong>${copy('observedPriceLoading')}</strong><p>${copy('observedPriceEvidenceNote')}</p></div>`;const selection=payload?.selection;if(!selection)return `<div class="empty-state">${icons('bookmark')}<strong>${copy('observedPriceNoSaved')}</strong><p>${copy('observedPriceEvidenceNote')}</p><button class="btn btn-primary" data-nav="saved">${copy('observedConfirmCancel')}</button></div>`;const products=Array.isArray(selection.products)?selection.products:[];const stores=Array.isArray(selection.stores)?selection.stores:[];const hasRows=products.length||stores.length;const prefill=payload?.prefill;const notice=selection.status==='DISPLAY_METADATA_INCOMPLETE'?copy('observedPriceBlocked'):selection.status==='READY_FOR_PREFILL_CHECK'?copy('observedPriceSelectionReady'):copy('observedPriceSelectionNeeded');return `<div class="card stack"><div class="split"><span class="section-label" style="margin:0">${copy('observedPriceSelectionCard')}</span><span class="pill orange">${safe(observedSelectionStatus(selection.status))}</span></div><div class="preview-notice">${icons('info')} ${copy('observedPriceEvidenceNote')}</div></div>${!hasRows?`<div class="empty-state">${icons('bookmark')}<strong>${copy('observedPriceNoSaved')}</strong><p>${copy('observedPriceEvidenceNote')}</p></div>`:`<div class="section-header"><strong>${safe(selection.productSectionTitle||copy('observedPriceChooseProduct'))}</strong></div><div class="stack">${products.map(row=>observedSelectionRow(row,'product')).join('')}</div><div class="section-header"><strong>${safe(selection.storeSectionTitle||copy('observedPriceChooseStore'))}</strong></div><div class="stack">${stores.map(row=>observedSelectionRow(row,'store')).join('')}</div><div class="card stack" style="margin-top:12px"><strong>${safe(notice)}</strong>${selection.notice?`<p class="micro">${copy('observedPriceBlocked')}</p>`:''}<div class="row" style="flex-wrap:wrap">${selection.clearSelectionAction?`<button class="tap-link" data-action="observed-select" data-kind="CLEAR_SELECTION">${icons('back')} ${copy('observedPriceClearProduct')} · ${copy('observedPriceClearStore')}</button>`:''}</div>${selection.checkAvailable?`<button class="btn btn-accent btn-fill" data-action="observed-check">${icons('arrow')} ${copy('observedPriceCheckPair')}</button>`:`<div class="preview-notice">${icons('info')} ${copy('observedPriceSelectionNeeded')}</div>`}</div>`}${prefill?`<div class="card stack" style="margin-top:12px"><div class="eyebrow">${safe(prefill.status==='IDENTITY_PREFILL_READY'?copy('observedPriceSelectionReady'):copy('observedPriceBlocked'))}</div><strong>${safe(observedPrefillMessage(prefill.message))}</strong>${prefill.productName?`<div class="small">${copy('observedConfirmIdentity')}: ${safe(prefill.productName)} · ${safe(prefill.storeDisplayName||'')}</div>`:''}</div>`:''}`}
function observedDraftStatus(draft){if(!draft)return copy('observedConfirmMissing');return draft.status==='NON_BYTE_INPUT_COMPLETE'?copy('observedConfirmReady'):copy('observedConfirmMissing')}
function observedProofSummary(proof){switch(String(proof?.status||'')){case'READY':return `${copy('observedConfirmProofReady')}${proof.byteLength?` · ${safe(proof.byteLength)} bytes`:''}`;case'REJECTED':return copy('observedConfirmProofRejected');case'AWAITING_SELECTION':return copy('observedConfirmProofWaiting');default:return copy('observedConfirmProofWaiting')}}
function observedActionStatus(value){switch(String(value||'')){case'CONFIRMED':return copy('observedConfirmSuccess');case'SUBMITTING':return copy('observedConfirmSubmitting');case'ERROR':return copy('observedConfirmError');case'READY':return copy('observedConfirmReady');default:return copy('observedConfirmMissing')}}
function nativeObservedConfirmation(payload){if(state.nativeObservedPricePending&&!payload?.confirmation)return `<div class="empty-state">${icons('check')}<strong>${copy('observedPriceLoading')}</strong><p>${copy('observedConfirmIntro')}</p></div>`;const confirmation=payload?.confirmation;if(!confirmation)return `<div class="empty-state">${icons('info')}<strong>${copy('observedPriceNoSaved')}</strong><button class="btn btn-primary" data-action="observed-cancel">${copy('observedConfirmCancel')}</button></div>`;const form=state.observedPriceForm;const draft=confirmation.draft;const proof=confirmation.proof||{};const action=confirmation.action||{};const submitEnabled=Boolean(action.actionEnabled);const statusMessage=action.status==='CONFIRMED'?copy('observedConfirmSuccess'):action.status==='SUBMITTING'?copy('observedConfirmSubmitting'):action.message?observedNativeMessage(action.message):copy('observedConfirmReady');const missing=Array.isArray(draft?.missing)?draft.missing:[];return `<div class="card stack"><div class="eyebrow">${copy('observedConfirmTitle')}</div><h1 class="page-title" style="margin:0">${copy('observedConfirmTitle')}</h1><p class="small" style="margin:0">${copy('observedConfirmIntro')}</p><div class="muted-panel"><div class="section-label" style="margin:0 0 5px">${copy('observedConfirmIdentity')}</div><strong>${safe(confirmation.productName||'')}</strong><div class="micro">${safe(confirmation.storeDisplayName||'')}</div></div></div><div class="card stack"><div class="section-header" style="margin:0"><strong>${copy('observedConfirmAmount')}</strong><span class="pill">ARS</span></div><div class="inline-form"><label class="small" style="flex:1">${copy('observedConfirmAmount')}<input id="observedAmount" class="inline-form-input" inputmode="decimal" value="${safe(form.amount)}" placeholder="${safe(copy('observedConfirmDecimalHint'))}"></label><label class="small" style="width:92px">${copy('observedConfirmCurrency')}<input id="observedCurrency" class="inline-form-input" value="${safe(form.currency)}" maxlength="12"></label></div>${confirmation.priceInputError?`<div class="preview-notice">${icons('info')} ${copy('observedConfirmInputError')}</div>`:''}<button class="btn btn-soft btn-fill" data-action="observed-set-price">${copy('observedConfirmSetPrice')}</button></div><div class="card stack"><div class="section-header" style="margin:0"><strong>${copy('observedConfirmDate')}</strong><span class="pill">${copy('observedConfirmTime')}</span></div><div class="inline-form"><label class="small" style="flex:1">${copy('observedConfirmDate')}<input id="observedDate" class="inline-form-input" inputmode="numeric" value="${safe(form.date)}" placeholder="${safe(copy('observedConfirmDateHint'))}"></label><label class="small" style="flex:1">${copy('observedConfirmTime')}<input id="observedTime" class="inline-form-input" inputmode="numeric" value="${safe(form.time)}" placeholder="${safe(copy('observedConfirmTimeHint'))}"></label><label class="small" style="width:78px">UTC<input id="observedOffset" class="inline-form-input" value="${safe(form.utcOffset)}" placeholder="${safe(copy('observedConfirmOffsetHint'))}"></label></div>${confirmation.observedAtInputError?`<div class="preview-notice">${icons('info')} ${copy('observedConfirmInputError')}</div>`:''}<button class="btn btn-soft btn-fill" data-action="observed-set-time">${copy('observedConfirmSetTime')}</button></div><div class="card stack"><div class="section-header" style="margin:0"><strong>${copy('observedConfirmProofReference')}</strong><span class="pill">${safe(observedProofSummary(proof))}</span></div><label class="small">${copy('observedConfirmProofReference')}<input id="observedArtifact" class="inline-form-input" value="${safe(form.artifactId)}" placeholder="${safe(copy('observedConfirmProofWaiting'))}"></label><div class="small">${copy('observedConfirmProofType')}</div><div class="row" style="flex-wrap:wrap"><button class="chip ${form.proofType==='RECEIPT'?'active':''}" data-action="observed-proof-type" data-proof-type="RECEIPT">${copy('observedConfirmReceipt')}</button><button class="chip ${form.proofType==='PRICE_TAG'?'active':''}" data-action="observed-proof-type" data-proof-type="PRICE_TAG">${copy('observedConfirmPriceTag')}</button></div><div class="row" style="flex-wrap:wrap"><button class="btn btn-outline" data-action="observed-proof-picker">${icons('camera')} ${copy('observedConfirmChooseFile')}</button><button class="btn btn-soft" data-action="observed-set-proof">${copy('observedConfirmSetProof')}</button></div>${confirmation.proofReferenceInputError?`<div class="preview-notice">${icons('info')} ${copy('observedConfirmInputError')}</div>`:''}</div><div class="card stack"><div class="section-header" style="margin:0"><strong>${copy('observedConfirmFinal')}</strong><span class="pill ${action.status==='CONFIRMED'?'green':''}">${safe(observedActionStatus(action.status))}</span></div><strong>${safe(observedDraftStatus(draft))}</strong>${missing.length?`<div class="stack">${missing.map(item=>`<div class="micro">• ${safe(item.label||'')}</div>`).join('')}</div>`:''}<p class="micro">${safe(statusMessage)}</p><div class="preview-notice">${icons('info')} ${copy('observedConfirmNotice')}</div><button class="btn btn-accent btn-fill" data-action="observed-submit" ${submitEnabled?'':'disabled'}>${icons('check')} ${copy('observedConfirmSubmit')}</button><button class="tap-link" data-action="observed-cancel">${icons('back')} ${copy('observedConfirmCancel')}</button></div>`}
function observedPrice(){return `<section class="content"><button class="detail-back" data-action="observed-cancel">${icons('back')} ${copy('observedConfirmCancel')}</button><div class="eyebrow">${copy('observedPriceLabel')}</div><h1 class="page-title">${copy('observedPriceTitle')}</h1><p class="hero-copy">${copy('observedPriceIntro')}</p><div class="stack" style="margin-top:12px">${nativeObservedSelection(state.nativeObservedPriceSelection?{selection:state.nativeObservedPriceSelection,prefill:state.nativeObservedPricePrefill}:null)}</div></section>`}
function observedConfirm(){return `<section class="content"><button class="detail-back" data-action="observed-cancel">${icons('back')} ${copy('observedConfirmCancel')}</button><div class="eyebrow">${copy('observedConfirmTitle')}</div><div class="stack" style="margin-top:12px">${nativeObservedConfirmation({confirmation:state.nativeObservedPriceConfirmation})}</div></section>`}
function stapleStatusLabel(value){switch(String(value||'')){case'READY_FOR_FACT_CHECK':return copy('stapleWatchStatusReady');case'DISPLAY_METADATA_INCOMPLETE':return copy('stapleWatchStatusBlocked');default:return copy('stapleWatchStatusNeeds')}}
function stapleWatchSelectionSummary(setup){const count=Number(setup?.watchedItemCount)||0;return `${count} ${copy('stapleWatchCount')} · ${setup?.usualStoreSelected?copy('stapleWatchStoreSet'):copy('stapleWatchStoreMissing')}`}
function stapleWatchProductRow(row){const action=row?.action||{};const key=action.key||'';const nextWatched=Boolean(action.watched);return `<div class="card saved-card"><div class="stack" style="gap:3px"><strong style="font-size:13px">${safe(row?.title||'')}</strong><span class="micro">${row?.watched?copy('stapleWatchStop'):copy('stapleWatchWatch')}</span></div><button class="btn ${row?.watched?'btn-soft':'btn-outline'}" data-action="staple-product" data-key="${safe(key)}" data-watched="${nextWatched?'true':'false'}">${row?.watched?icons('check'):icons('plus')} ${row?.watched?copy('stapleWatchStop'):copy('stapleWatchWatch')}</button></div>`}
function stapleWatchStoreRow(row){const action=row?.action||{};const selected=Boolean(row?.usualStore);const kind=String(action.kind||'');const key=action.key||'';return `<div class="card saved-card"><div class="stack" style="gap:3px"><strong style="font-size:13px">${safe(row?.title||'')}</strong><span class="micro">${selected?copy('stapleWatchClearStore'):copy('stapleWatchUseStore')}</span></div><button class="btn ${selected?'btn-soft':'btn-outline'}" data-action="staple-store" data-kind="${safe(kind)}" data-key="${safe(key)}">${selected?icons('check'):icons('plus')} ${selected?copy('stapleWatchClearStore'):copy('stapleWatchUseStore')}</button></div>`}
function nativeStapleWatch(payload){if(state.nativeStapleWatchPending&&!payload?.state)return `<div class="empty-state">${icons('bookmark')}<strong>${copy('stapleWatchLoading')}</strong><p>${copy('nativeToolDetail')}</p></div>`;const setup=payload?.state;if(!setup)return `<div class="empty-state">${icons('bookmark')}<strong>${copy('stapleWatchNeedTwo')}</strong><p>${copy('nativeSavedIdentityNote')}</p><button class="btn btn-primary" data-nav="search">${copy('searchProducts')} ${icons('arrow')}</button></div>`;const products=Array.isArray(setup.products)?setup.products:[];const stores=Array.isArray(setup.stores)?setup.stores:[];const capability=String(setup.factCheckCapability||'');const blocked=setup.status==='DISPLAY_METADATA_INCOMPLETE';const ready=setup.status==='READY_FOR_FACT_CHECK';const progress=setup.factResolutionProgress;return `<div class="card stack"><div class="split"><span class="section-label" style="margin:0">${copy('stapleWatchSummary')}</span><span class="pill ${ready?'green':'orange'}">${safe(stapleStatusLabel(setup.status))}</span></div><strong>${safe(stapleWatchSelectionSummary(setup))}</strong><p class="micro">${safe(blocked?copy('stapleWatchMetadata'):ready?copy('stapleWatchReady'):copy('stapleWatchNeedTwo'))}</p></div>${products.length?`<div class="section-header"><strong>${copy('stapleWatchProducts')}</strong></div><div class="stack">${products.map(stapleWatchProductRow).join('')}</div>`:`<div class="empty-state">${icons('bookmark')}<strong>${copy('stapleWatchNeedTwo')}</strong><p>${copy('nativeSavedIdentityNote')}</p></div>`}${stores.length?`<div class="section-header"><strong>${copy('stapleWatchStore')}</strong></div><div class="stack">${stores.map(stapleWatchStoreRow).join('')}</div>`:''}${progress?`<div class="card stack"><div class="section-label">${copy('stapleWatchFactProgress')}</div><strong>${Number(progress.resolvedRequirementCount)||0} / ${Number(progress.totalRequirementCount)||0} ${copy('stapleWatchFactCount')}</strong><p class="micro">${safe(state.language===LANGUAGES.EN?progress.guidance:copy('stapleWatchCapability'))}</p></div>`:''}${capability==='NOT_CONFIGURED'?`<div class="card stack"><strong>${copy('stapleWatchCapability')}</strong><p class="micro">${copy('stapleWatchClassicDetail')}</p><button class="btn btn-soft btn-fill" data-action="staple-classic">${icons('arrow')} ${copy('stapleWatchClassic')}</button></div>`:''}${setup.continueAvailable?`<button class="btn btn-accent btn-fill" data-action="staple-submit">${icons('arrow')} ${copy('stapleWatchContinue')}</button>`:''}${setup.watchedItemCount||setup.usualStoreSelected?`<button class="tap-link" data-action="staple-clear">${icons('back')} ${copy('stapleWatchClear')}</button>`:''}`}
function stapleWatch(){return `<section class="content"><button class="detail-back" data-action="staple-cancel">${icons('back')} ${copy('stapleWatchBack')}</button><div class="eyebrow">${copy('stapleWatchLabel')}</div><h1 class="page-title">${copy('stapleWatchTitle')}</h1><p class="hero-copy">${copy('stapleWatchIntro')}</p><div class="stack" style="margin-top:12px">${nativeStapleWatch(state.nativeStapleWatchState)}</div></section>`}
function nativeHistorySource(value){switch(String(value||'')){case'Scan & compare':return copy('historySourceScan');case'Is this a good price?':return copy('historySourceGoodPrice');default:return safe(value||'')}}
function nativeHistoryBasis(value){switch(String(value||'')){case'Current price':return copy('historyBasisCurrent');case'Member price':return copy('historyBasisMember');default:return safe(value||'')}}
function nativeHistoryMovement(value){const raw=String(value||'');if(raw.startsWith('Down from previous'))return `${copy('historyMovementDown')} ${safe(raw.slice('Down from previous'.length).trim())}`;if(raw.startsWith('Up from previous'))return `${copy('historyMovementUp')} ${safe(raw.slice('Up from previous'.length).trim())}`;if(raw==='Same as previous observation')return copy('historyMovementSame');return safe(raw)}
function nativeHistoryFact(value){const raw=String(value||'');if(state.language===LANGUAGES.EN)return safe(raw);return safe(raw.replace(/(^|[^A-Za-z0-9])(-?\d+\.\d+)(?![A-Za-z0-9])/g,(match,prefix,number)=>prefix+number.replace('.',',')))}
function nativeHistoryRows(history){const rows=Array.isArray(history?.rows)?history.rows:[];return rows.map(row=>`<article class="card saved-card native-history-row"><div class="stack"><div class="eyebrow">${Number(row.observationCount)||0} ${copy(Number(row.observationCount)===1?'historyObservation':'historyObservations')} · ${nativeHistorySource(row.sourceText)}</div><strong style="font-size:14px">${safe(row.displayName||'')}</strong><div class="number-lg" style="font-size:22px">${nativeHistoryFact(row.latestPriceText)}</div><div class="micro">${copy('historyLastObserved')}: ${nativeHistoryFact(row.latestObservedText)}</div><div class="small">${copy('historyLowestPrice')}: ${nativeHistoryFact(row.lowestPriceText)}</div><div class="small">${copy('historyUnitRate')}: ${nativeHistoryFact(row.latestUnitRateText)}</div><div class="small">${copy('historyRange')}: ${nativeHistoryFact(row.rangeText)}</div><div class="micro">${copy('historyPackage')}: ${nativeHistoryFact(row.packageText)} · ${nativeHistoryBasis(row.priceBasisText)}</div>${row.recentMovementText?`<div class="micro">${nativeHistoryMovement(row.recentMovementText)}</div>`:''}${row.promotionText?`<div class="micro">${copy('historyPromotion')}: ${safe(String(row.promotionText).replace(/^Promotion:\s*/i,''))}</div>`:''}</div></article>`).join('')}
function nativePrivateHistorySummary(payload){const history=payload?.privateHistory;if(!history||history.status==='UNAVAILABLE')return `<div class="card stack"><div class="section-label">${copy('nativeHistoryTitle')}</div><strong>${copy('nativeHistoryUnavailable')}</strong><p class="micro">${copy('nativeHistoryDetail')}</p><button class="tap-link" data-action="open-private-history">${copy('reviewPrivateHistory')} ${icons('arrow')}</button></div>`;if(history.status==='EMPTY')return `<div class="card stack"><div class="section-label">${copy('nativeHistoryTitle')}</div><strong>${copy('nativeHistoryEmpty')}</strong><p class="micro">${copy('nativeHistoryDetail')}</p><button class="tap-link" data-action="open-private-history">${copy('reviewPrivateHistory')} ${icons('arrow')}</button></div>`;const observationCount=Number(history.observationCount)||0;const exactCount=Number(history.exactHistoryCount)||0;const countLabel=`${observationCount} ${copy(observationCount===1?'historyObservation':'historyObservations')}`;return `<div class="card stack"><div class="section-label">${copy('nativeHistoryTitle')}</div><strong>${countLabel} · ${exactCount} ${copy('historyExactPackage')}</strong><p class="micro">${countLabel} ${copy('nativeHistoryAvailable')} · ${copy('nativeHistoryDetail')}</p>${history.latestDisplayName?`<div class="micro"><strong>${copy('historyLatest')}:</strong> ${safe(history.latestDisplayName)}</div>`:''}${history.rows?.length?`<div class="stack" style="margin-top:4px">${nativeHistoryRows(history)}</div>`:''}<button class="tap-link" data-action="open-private-history">${copy('reviewPrivateHistory')} ${icons('arrow')}</button></div>`}
function nativePurchaseHistoryUnavailable(){return `<div class="card stack"><div class="section-label">${copy('purchaseHistoryUnavailable')}</div><strong>${copy('purchaseHistoryUnavailableTitle')}</strong><p class="micro">${copy('purchaseHistoryUnavailableDetail')}</p></div>`}
function privateHistory(){const payload=state.nativeSavedState;const history=payload?.privateHistory;if(state.nativeSavedPending)return `<section class="content"><button class="detail-back" data-action="back">${icons('back')} ${copy('back')}</button><div class="eyebrow">${copy('nativeHistoryTitle')}</div><h1 class="page-title">${copy('reviewPrivateHistory')}</h1><div class="empty-state">${icons('arrow')}<strong>${copy('nativeLoading')}</strong></div></section>`;if(!history||history.status==='UNAVAILABLE')return `<section class="content"><button class="detail-back" data-action="back">${icons('back')} ${copy('back')}</button><div class="eyebrow">${copy('nativeHistoryTitle')}</div><h1 class="page-title">${copy('reviewPrivateHistory')}</h1><div class="card stack"><strong>${copy('nativeHistoryUnavailable')}</strong><p class="micro">${copy('nativeHistoryDetail')}</p><button class="btn btn-soft btn-fill" data-action="open-private-history">${copy('reviewPrivateHistory')} ${icons('arrow')}</button></div></section>`;if(history.status==='EMPTY')return `<section class="content"><button class="detail-back" data-action="back">${icons('back')} ${copy('back')}</button><div class="eyebrow">${copy('nativeHistoryTitle')}</div><h1 class="page-title">${copy('reviewPrivateHistory')}</h1><div class="empty-state">${icons('arrow')}<strong>${copy('nativeHistoryEmpty')}</strong><p>${copy('nativeHistoryDetail')}</p><button class="btn btn-soft" data-action="open-native-tool" data-destination="PRIVATE_PRICE_HISTORY">${copy('reviewPrivateHistory')} ${icons('arrow')}</button></div></section>`;const observationCount=Number(history.observationCount)||0;const exactCount=Number(history.exactHistoryCount)||0;const countLabel=`${observationCount} ${copy(observationCount===1?'historyObservation':'historyObservations')}`;return `<section class="content"><button class="detail-back" data-action="back">${icons('back')} ${copy('back')}</button><div class="eyebrow">${copy('nativeHistoryTitle')}</div><h1 class="page-title">${copy('reviewPrivateHistory')}</h1><p class="hero-copy">${countLabel} · ${exactCount} ${copy('historyExactPackage')}</p><div class="preview-notice">${icons('info')} ${copy('nativeHistoryDetail')}</div><div class="stack" style="margin-top:12px">${nativeHistoryRows(history)}</div><button class="btn btn-soft btn-fill" data-action="open-native-tool" data-destination="PRIVATE_PRICE_HISTORY">${copy('reviewPrivateHistory')} ${icons('arrow')}</button></section>`}
function saved(){const ids=[...state.saved].filter(id=>get(id));const native=nativeDataMode();return `<section class="content"><div class="eyebrow">${native?copy('nativeSavedTitle'):copy('personalList')}</div><h1 class="page-title">${copy('savedTitle')}</h1><p class="hero-copy">${native?copy('nativeSavedIntro'):copy('favorites')}</p><div class="stack" style="margin-top:12px"><button class="btn btn-soft btn-fill" data-action="${native?'use-samples-saved':'native-saved'}">${native?copy('useExamples'):copy('useValuePilotSaved')}</button></div><div class="card stack" style="margin-top:12px"><button class="tap-link" data-action="open-native-saved-tools">${icons('arrow')} ${copy('openSavedTools')}</button><p class="micro">${copy('openSavedToolsDetail')}</p><div class="stack" style="margin-top:8px"><button class="tap-link" data-action="open-observed-price">${icons('plus')} ${copy('observedPriceTool')}</button><button class="tap-link" data-action="open-native-journey" data-destination="GOOD_PRICE_CHECK">${icons('check')} ${copy('goodPriceTool')}</button><button class="tap-link" data-action="open-staple-watch">${icons('bookmark')} ${copy('stapleWatchTool')}</button><button class="tap-link" data-action="open-private-history">${icons('arrow')} ${copy('privateHistoryTool')}</button></div><p class="micro">${copy('nativeToolDetail')}</p></div>${native?nativeSavedResults(state.nativeSavedState):ids.length?`<div class="stack" style="margin-top:15px">${ids.map(id=>{const p=get(id);return `<div class="card saved-card"><div><strong style="font-size:13px">${safe(p.brand)} · ${safe(p.name)}</strong><div class="micro">${safe(p.quantity)} · ${copy('fictitiousInfo')}</div></div><div class="row"><button class="icon-button" data-action="detail" data-id="${id}" aria-label="${safe(copy('openDetails'))}">${icons('arrow')}</button><button class="bookmark-button is-saved" data-action="save" data-id="${id}" aria-label="${safe(copy('removeSavedProductAria'))}">${icons('bookmark')}</button></div></div>`}).join('')}</div>`:`<div class="empty-state">${icons('bookmark')}<strong>${copy('savePrompt')}</strong><p>${copy('tapBookmark')}</p><button class="btn btn-primary" data-nav="search">${copy('searchProducts')} ${icons('arrow')}</button></div>`}${native?nativePrivateHistorySummary(state.nativeSavedState):''}${native?nativePurchaseHistoryUnavailable():''}<div class="section-header"><strong>${copy('otherTools')}</strong></div><div class="card stack"><button class="tap-link" data-nav="trip">${icons('route')} ${copy('tripEstimator')}</button><button class="tap-link" data-action="open-native-journey" data-destination="COMPARE">${icons('sliders')} ${copy('compareTool')}</button><p class="micro">${copy('compareToolDetail')}</p></div></section>`}
function trip(){const native=nativeDataMode()&&state.nativeTripEnabled;return `<section class="content"><button class="detail-back" data-action="back">${icons('back')} ${copy('back')}</button><div class="eyebrow">${native?copy('nativeTripTitle'):copy('tripDemo')}</div><h1 class="page-title">${copy('tripTitle')}</h1><p class="hero-copy">${native?copy('nativeTripIntro'):copy('tripDescription')}</p><div class="stack" style="margin-top:12px"><button class="btn btn-soft btn-fill" data-action="${native?'use-sample-trip':'native-trip'}">${native?copy('useExamples'):copy('useValuePilotTrip')}</button></div><div class="card" style="margin-top:16px"><form id="tripForm" class="stack"><label class="small">${copy('distance')}<input name="distance" inputmode="decimal" type="number" required min="0" step="0.1" value="${safe(state.tripInputs.distance)}" placeholder="${safe(copy('exampleDistance'))}" class="inline-form-input"></label><label class="small">${copy('consumption')}<input name="consumption" inputmode="decimal" type="number" required min="0" step="0.1" value="${safe(state.tripInputs.consumption)}" placeholder="${safe(copy('exampleConsumption'))}" class="inline-form-input"></label><label class="small">${copy('fuelPrice')}<input name="fuel" inputmode="decimal" type="number" required min="0" step="0.1" value="${safe(state.tripInputs.fuel)}" placeholder="${safe(copy('fuelPlaceholder'))}" class="inline-form-input"></label><label class="small">${copy('tolls')}<input name="tolls" inputmode="decimal" type="number" min="0" step="0.1" value="${safe(state.tripInputs.tolls)}" class="inline-form-input"></label><label class="small">${copy('parking')}<input name="parking" inputmode="decimal" type="number" min="0" step="0.1" value="${safe(state.tripInputs.parking)}" class="inline-form-input"></label><button type="submit" class="btn btn-primary btn-fill">${icons('route')} ${copy('calculate')}</button></form>${native?nativeTripResults(state.nativeTripState):'<div id="tripResult" hidden></div>'}</div><div class="preview-notice" style="margin-top:14px">${icons('info')} ${copy('tripNotice')}</div></section>`}
function settings(){return `<section class="content"><button class="detail-back" data-action="back">${icons('back')} ${copy('back')}</button><div class="eyebrow">${copy('previewPreferences')}</div><h1 class="page-title">${copy('personalize')}</h1><div class="settings-panel"><div class="setting-row"><span>${copy('visualTheme')}</span><select id="themeChoice" aria-label="${safe(copy('chooseTheme'))}"><option value="light" ${state.theme==='light'?'selected':''}>${copy('light')}</option><option value="dark" ${state.theme==='dark'?'selected':''}>${copy('dark')}</option></select></div><div class="setting-row"><span>${copy('language')}</span><div class="language-toggle" role="group" aria-label="${safe(copy('language'))}"><button type="button" data-language="en" aria-pressed="${state.language===LANGUAGES.EN?'true':'false'}">EN</button><span aria-hidden="true">|</span><button type="button" data-language="es-AR" aria-pressed="${state.language===LANGUAGES.ES_AR?'true':'false'}">ES</button></div></div><div class="setting-row"><span>${copy('market')}</span><span class="small">Buenos Aires (CABA)</span></div></div><div class="preview-notice" style="margin-top:15px">${icons('info')} ${copy('settingsNotice')}</div></section>`}

function openNativeBasket(){try{if(window.ValuePilotHost&&typeof window.ValuePilotHost.postMessage==='function'){window.ValuePilotHost.postMessage(JSON.stringify({type:'OPEN_NATIVE_BASKET'}));return true}}catch(_){ }flash(copy('nativeBasketUnavailable'));return false}function openNativeSavedTools(destination='SAVED'){const allowed=new Set(['SAVED','OBSERVED_PRICE_SELECTION','STAPLE_WATCH_SETUP','PRIVATE_PRICE_HISTORY']);const next=allowed.has(destination)?destination:'SAVED';try{if(window.ValuePilotHost&&typeof window.ValuePilotHost.postMessage==='function'){window.ValuePilotHost.postMessage(JSON.stringify({type:'OPEN_NATIVE_SAVED_TOOLS',destination:next}));return true}}catch(_){ }flash(copy('nativeSavedPersistence'));return false}
function openNativeJourney(destination){const allowed=new Set(['GOOD_PRICE_CHECK','COMPARE']);if(!allowed.has(destination)){flash(copy('nativeJourneyUnavailable'));return false}try{if(window.ValuePilotHost&&typeof window.ValuePilotHost.postMessage==='function'){window.ValuePilotHost.postMessage(JSON.stringify({type:'OPEN_NATIVE_JOURNEY',destination}));return true}}catch(_){ }flash(copy('nativeJourneyUnavailable'));return false}
// Event delegation for a small, auditable WebView surface.
document.addEventListener('click',event=>{if(state.matrixSuppressClickUntil&&Date.now()<state.matrixSuppressClickUntil&&event.target.closest('#matrixScroll')){state.matrixSuppressClickUntil=0;event.preventDefault();event.stopImmediatePropagation()}},true);
 document.addEventListener('click',(event)=>{const languageButton=event.target.closest('[data-language]');if(languageButton){event.preventDefault();setLanguage(languageButton.dataset.language);return}const el=event.target.closest('[data-action],[data-nav]');if(!el)return;event.preventDefault();const a=el.dataset.action,id=el.dataset.id,identityKey=el.dataset.identityKey,offerKey=el.dataset.offerKey,displayName=el.dataset.displayName,brand=el.dataset.brand,quantity=el.dataset.quantity,query=el.dataset.query;if(el.dataset.nav){navigate(el.dataset.nav,{from:state.page});return}
switch(a){case'go-search':{state.query=document.querySelector('#homeQuery')?.value||'leche';navigate('search',{from:'home'});if(state.nativeSearchEnabled)requestNativeSearch(state.query);break}case'back':back();break;case'detail':navigate('detail',{selected:id,from:state.page});break;case'photos':openPhotos(id);break;case'native-search':enableNativeSearch();break;case'use-samples':disableNativeSearch();break;case'native-saved':enableNativeSaved();break;case'use-samples-saved':disableNativeSaved();break;case'native-load-more':requestNativeSearchLoadMore();break;case'native-clarification':requestNativeSearch(el.dataset.query||state.query);break;case'native-save':requestNativeSave(id);break;case'native-detail':requestNativeProductDetail(identityKey,query);break;case'native-map':requestNativeMap(identityKey,offerKey,query);break;case'demo-map':flash(copy('demoMapUnavailable'));break;case'matrix-sort':state.matrixSort=el.dataset.sort||'unit';render();break;case'native-detail-save':requestNativeDetailSave();break;case'native-remove-saved':requestNativeRemove(identityKey);break;case'native-refresh-saved':requestNativeSaved();break;case'native-plan':requestNativeBasketPlan();break;case'native-good-price':requestNativeGoodPrice(identityKey,displayName);break;case'native-saved-photos':requestNativeSavedGoogleImages(brand,displayName,quantity);break;case'open-native-saved-tools':openNativeSavedTools('SAVED');break;case'open-observed-price':navigate('observed-price');break;case'open-staple-watch':navigate('staple-watch');break;case'open-private-history':navigate('private-history');break;case'observed-select':requestNativeObservedSelection(el.dataset.kind,el.dataset.key);break;case'observed-check':requestNativeObservedPrefill();break;case'observed-set-price':requestNativeObservedAmount();break;case'observed-set-time':requestNativeObservedTime();break;case'observed-proof-type':state.observedPriceForm.proofType=el.dataset.proofType||'';render();break;case'observed-set-proof':requestNativeObservedProof();break;case'observed-proof-picker':requestNativeObservedProofPicker();break;case'observed-submit':requestNativeObservedSubmit();break;case'observed-cancel':requestNativeObservedCancel();break;case'staple-product':requestNativeStapleProduct(el.dataset.key,el.dataset.watched==='true');break;case'staple-store':el.dataset.kind==='CLEAR_STORE'?requestNativeStapleClearStore():requestNativeStapleStore(el.dataset.key);break;case'staple-classic':openNativeSavedTools('STAPLE_WATCH_SETUP');break;case'staple-clear':requestNativeStapleClearSelection();break;case'staple-submit':requestNativeStapleSubmit();break;case'staple-cancel':requestNativeStapleCancel();break;case'open-native-basket':openNativeBasket();break;case'open-native-tool':openNativeSavedTools(el.dataset.destination||'SAVED');break;case'open-native-journey':openNativeJourney(el.dataset.destination||'COMPARE');break;case'native-trip':enableNativeTrip();break;case'use-sample-trip':disableNativeTrip();break;case'add':add(id);break;case'add-detail':add(state.selected,state.detailQuantity);break;case'save':toggleSaved(id);break;case'basket-plus':changeQty(id,1);break;case'basket-minus':changeQty(id,-1);break;case'detail-plus':state.detailQuantity=Math.min(99,state.detailQuantity+1);render();break;case'detail-minus':state.detailQuantity=Math.max(1,state.detailQuantity-1);render();break;case'sort':state.sort=state.sort==='price'?'name':state.sort==='name'?'reverse':'price';render();break;case'category':state.category=el.dataset.category;if(state.page==='home'){state.query=state.category;state.category='Todos';navigate('search',{from:'home'})}else render();break;case'show-all':state.query='';state.category='Todos';render();break;case'clear-basket':state.basket.clear();render();flash(copy('toastCleared'));break;}
});
document.querySelector('#settingsButton').addEventListener('click',()=>navigate('settings'));
document.querySelector('#themeToggle').addEventListener('click',()=>setTheme(state.theme==='light'?'dark':'light'));
document.addEventListener('change',(e)=>{if(e.target.id==='themeChoice')setTheme(e.target.value)});
 document.addEventListener('submit',e=>{if(e.target.id==='searchForm'){e.preventDefault();const input=e.target.querySelector('input');state.query=input.value;state.matrixScrollTop=0;state.matrixScrollLeft=0;if(state.nativeSearchEnabled){requestNativeSearch(state.query)}else{const area=document.querySelector('#resultsArea');if(area)area.innerHTML=searchUnavailable()}document.activeElement.blur();return}if(e.target.id==='tripForm'){e.preventDefault();const fd=new FormData(e.target);for(const name of Object.keys(state.tripInputs))state.tripInputs[name]=String(fd.get(name)||'');const d=Number(state.tripInputs.distance),c=Number(state.tripInputs.consumption),f=Number(state.tripInputs.fuel),t=Number(state.tripInputs.tolls),p=Number(state.tripInputs.parking);if([d,c,f,t,p].some(v=>!Number.isFinite(v)||v<0)||c<=0){flash(copy('invalidInputs'));return}if(nativeDataMode()&&state.nativeTripEnabled){requestNativeTrip({distance:d,consumption:c,fuel:f,tolls:t,parking:p});return}const roundTrip=d*2;const cost=roundTrip*c*f/100+t+p;const result=document.querySelector('#tripResult');result.hidden=false;result.innerHTML=`<div class="summary-total" style="margin-top:14px"><div style="font-size:12px">${copy('estimated')}</div><div class="number-lg" style="margin-top:8px">${currency(cost)}</div><div class="micro" style="color:#ddd">${money(roundTrip)} km · ${Number((roundTrip*c/100).toFixed(2))} L + ${currency(t+p)} ${copy('additional')}</div></div>`;return}});
document.addEventListener('change',(e)=>{if(e.target.id==='matrixStore'){state.matrixStore=e.target.value||'all';render()}else if(e.target.id==='matrixSort'){state.matrixSort=e.target.value||'unit';render()}});
document.addEventListener('input',(e)=>{if(e.target.id==='searchQuery'){state.query=e.target.value;if(!state.nativeSearchEnabled){state.matrixScrollTop=0;state.matrixScrollLeft=0;const area=document.querySelector('#resultsArea');if(area)area.innerHTML=searchUnavailable()}}if(e.target.id==='observedAmount')state.observedPriceForm.amount=e.target.value;if(e.target.id==='observedCurrency')state.observedPriceForm.currency=e.target.value;if(e.target.id==='observedDate')state.observedPriceForm.date=e.target.value;if(e.target.id==='observedTime')state.observedPriceForm.time=e.target.value;if(e.target.id==='observedOffset')state.observedPriceForm.utcOffset=e.target.value;if(e.target.id==='observedArtifact')state.observedPriceForm.artifactId=e.target.value;if(e.target.closest('#tripForm')){if(Object.prototype.hasOwnProperty.call(state.tripInputs,e.target.name))state.tripInputs[e.target.name]=e.target.value;const result=document.querySelector('#tripResult');if(result)result.hidden=true}});
document.addEventListener('click',e=>{if(e.target.closest('#clearQuery')){state.query='';state.nativeSearchState=null;state.nativeSearchPending=false;document.querySelector('#searchQuery').value='';state.matrixScrollTop=0;state.matrixScrollLeft=0;document.querySelector('#resultsArea').innerHTML=state.nativeSearchEnabled?nativeResults(null):searchUnavailable();document.querySelector('#searchQuery').focus()}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('tr.matrix-row')){e.preventDefault();e.target.click();return}if(e.key==='Escape'&&state.page!=='home'){back()}});
// Android host adapter: this is non-visual and keeps system back behavior inside the
// prototype without exposing the demo state to a privileged native interface.
 window.ValuePilotHtmlPreview = Object.freeze({
  back:()=>{if(state.page==='home')return false;back();return true},
  page:()=>state.page,
  language:()=>state.language,
  setLanguage:(language)=>{setLanguage(language,{persist:false});return state.language},
  receiveNativeSearch:(payload)=>{receiveNativeSearch(payload);return true},
  receiveNativeProductDetail:(payload)=>{receiveNativeProductDetail(payload);return true},
  refreshNativeSaved:()=>{if(!state.nativeSavedEnabled||state.nativeSavedPending)return false;requestNativeSaved();return true},
  receiveNativeActionNotice:(payload)=>receiveNativeActionNotice(payload),
   receiveNativeSaved:(payload)=>{receiveNativeSaved(payload);return true},
  receiveNativeTrip:(payload)=>{receiveNativeTrip(payload);return true},
  receiveNativeObservedPrice:(payload)=>{receiveNativeObservedPrice(payload);return true},
  receiveNativeStapleWatch:(payload)=>{receiveNativeStapleWatch(payload);return true},
  returnToSaved:()=>{state.nativeStapleWatchPending=false;state.nativeStapleWatchState=null;navigate('saved',{skipHistory:true});return true},
});
// Security: this demo never persists, parses, or uses external image results.
render();
